    private val allProductsBySku: Map<String, Product> by lazy {
        (BravoCatalogData.BRAVO_PRODUCTS + ARCA_PRODUCTS).associateBy { it.sku }
    }

    fun getAllProducts(): List<Product> = BravoCatalogData.BRAVO_PRODUCTS + ARCA_PRODUCTS

    fun getProductsForStore(store: StoreMode): List<Product> =
        if (store == StoreMode.ARCA) ARCA_PRODUCTS else BravoCatalogData.BRAVO_PRODUCTS

    fun getSectionsForStore(store: StoreMode): List<CatalogSection> =
        if (store == StoreMode.ARCA) ARCA_SECTIONS else BravoCatalogData.BRAVO_SECTIONS

    fun findProductBySku(sku: String): Product? = allProductsBySku[sku]
}
